To count the number of strongly connected components in a directed graph, we can use the Kosaraju's algorithm. This algorithm involves two main steps: first, we perform a depth-first search (DFS) on the graph to compute the finish times of each vertex. Then, we perform another DFS on the transpose graph (where all edges are reversed) using the finish times from the first DFS as the order of exploration. The number of strongly connected components is equal to the number of trees in the second DFS forest.

Here is the Python implementation of Kosaraju's algorithm:

```python
def dfs(graph, vertex, visited, finish_times):
    visited[vertex] = True
    finish_times[vertex] = len(finish_times)
    for neighbor in graph[vertex]:
        if not visited[neighbor]:
            dfs(graph, neighbor, visited, finish_times)
    return finish_times[vertex]

def transpose_graph(graph):
    transposed_graph = {vertex: [] for vertex in graph}
    for vertex in graph:
        for neighbor in graph[vertex]:
            transposed_graph[neighbor].append(vertex)
    return transposed_graph

def strongly_connected_components_count(node_count, edges):
    graph = {i: [] for i in range(node_count)}
    for edge in edges:
        graph[edge[0]].append(edge[1])

    visited = [False] * node_count
    finish_times = []
    for vertex in range(node_count):
        if not visited[vertex]:
            finish_times.append(dfs(graph, vertex, visited, finish_times))

    transposed_graph = transpose_graph(graph)
    visited = [False] * node_count
    component_count = 0
    for vertex in range(node_count):
        if not visited[vertex]:
            component_count += dfs(transposed_graph, vertex, visited, finish_times)

    return component_count

